class SummationCalculator(ABC):
    @abstractmethod
    def compute(self, shapes: list):
        pass

class VolumeSummationCalculator(SummationCalculator):
    def compute(self, shapes: list):
        return sum(shape.volume() for shape in shapes if isinstance(shape, Shape))
